'use strict';
// One-time patch: text animations and templates, the extra Adjust sliders (highlights, shadows, tint, hue, grain) and video effects (shake, glitch, blur, flash, RGB split, film grain).
// Run from the project folder:   node tools/apply-look-text.js
// It checks that every spot it needs to change is found exactly once BEFORE writing anything, so it does everything or nothing.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const B = {"animJs":"'use strict';\n/* Naki animation: keyframes and overlay geometry. Pure helpers shared by the project model, the editor preview and both export engines,\n   so all of them agree on where an overlay is, and how big, at every moment.\n   A keyframe list is [[ms since the clip started, value], ...] in time order. Between two keyframes the value changes in a straight line;\n   before the first and after the last it stays put. */\nvar NakiAnim = (function () {\n  var OVERLAY = { x: 0.75, y: 0.25, size: 0.35, rot: 0, opacity: 1 };   // centre (fraction of the frame), width (fraction of the frame width), degrees, 0 to 1\n  var PICTURE = { zoom: 1, x: 0, y: 0 };\n  var RANGE = { overlay: { x: [0, 1], y: [0, 1], size: [0.05, 1.5], rot: [-180, 180], opacity: [0, 1] }, picture: { zoom: [1, 4], x: [-1, 1], y: [-1, 1] } };\n\n  function kfValue(points, rel) {\n    if (!points || !points.length) return null;\n    if (rel <= points[0][0]) return points[0][1];\n    for (var i = 1; i < points.length; i++) {\n      if (rel <= points[i][0]) {\n        var a = points[i - 1], b = points[i];\n        return b[0] === a[0] ? b[1] : a[1] + (b[1] - a[1]) * (rel - a[0]) / (b[0] - a[0]);\n      }\n    }\n    return points[points.length - 1][1];\n  }\n  // The value of one property of an overlay clip ('overlay') or a picture clip's zoom / pan ('picture') at relMs since the clip started.\n  function valueOf(c, kind, prop, relMs) {\n    var pts = c.kf && c.kf[prop];\n    if (pts && pts.length) return kfValue(pts, relMs);\n    if (kind === 'overlay') return c[prop] != null ? c[prop] : OVERLAY[prop];\n    return c.transform && c.transform[prop] != null ? c.transform[prop] : PICTURE[prop];\n  }\n  function overlayState(o, relMs) {\n    var s = {};\n    ['x', 'y', 'size', 'rot', 'opacity'].forEach(function (k) { s[k] = valueOf(o, 'overlay', k, relMs); });\n    return s;\n  }\n  // The picture clip's transform { zoom, x, y, rot, flipH } at relMs, with its zoom / pan keyframes applied.\n  function pictureTransform(t, kf, relMs) {\n    var o = Object.assign({ zoom: 1, x: 0, y: 0, rot: 0, flipH: false }, t || {});\n    ['zoom', 'x', 'y'].forEach(function (k) { if (kf && kf[k] && kf[k].length) o[k] = kfValue(kf[k], relMs); });\n    return o;\n  }\n  // The span of an export plan with its keyframes worked out for one moment (relMs since the span started).\n  function spanAt(sp, relMs) { return sp.kf ? Object.assign({}, sp, { transform: pictureTransform(sp.transform, sp.kf, relMs) }) : sp; }\n  // Where an overlay is in a W x H frame: centre and size in pixels, turn in degrees, opacity. aspect = picture height / width.\n  function overlayRect(o, s, W, H) {\n    var aspect = o.w > 0 && o.h > 0 ? o.h / o.w : 9 / 16, w = Math.max(2, s.size * W);\n    return { cx: s.x * W, cy: s.y * H, w: w, h: w * aspect, rot: s.rot, opacity: s.opacity };\n  }\n  // All keyframe times move earlier by deltaMs (negative: later).\n  function shiftKf(kf, deltaMs) {\n    if (!kf) return kf;\n    var out = {}; Object.keys(kf).forEach(function (k) { out[k] = kf[k].map(function (p) { return [p[0] - deltaMs, p[1]]; }); });\n    return out;\n  }\n  // An ffmpeg expression for a keyframe list. tv is the name of the time variable in seconds ('t', or 'T' inside geq). shiftMs is added to every\n  // keyframe time; mul converts the keyframe clock to the clock the filter sees (the speed of the picture).\n  function kfExpr(points, shiftMs, mul, tv) {\n    tv = tv || 't'; mul = mul || 1;\n    var P = points.map(function (p) { return [(p[0] + (shiftMs || 0)) * mul / 1000, p[1]]; });\n    function f(n) { return String(Math.round(n * 10000) / 10000); }\n    var e = f(P[P.length - 1][1]);\n    for (var i = P.length - 1; i > 0; i--) {\n      var a = P[i - 1], b = P[i];\n      var seg = b[0] === a[0] ? f(b[1]) : f(a[1]) + '+(' + f(b[1] - a[1]) + ')*(' + tv + '-(' + f(a[0]) + '))/' + f(b[0] - a[0]);\n      e = 'if(lt(' + tv + ',' + f(b[0]) + '),' + seg + ',' + e + ')';\n    }\n    return 'if(lt(' + tv + ',' + f(P[0][0]) + '),' + f(P[0][1]) + ',' + e + ')';\n  }\n\n  // ---- text animation: how a title looks at relMs after it appeared, for a title that is durMs long ----\n  // anim = { in, out: 'none' | 'fade' | 'slideup' | 'slidedown' | 'pop', loop: 'none' | 'pulse' | 'float', inMs, outMs }.\n  // alpha 0 to 1, dy = how far it is moved down (a fraction of the picture height), scale about the title's own anchor point.\n  var TEXT_IN_OUT = ['none', 'fade', 'slideup', 'slidedown', 'pop'], TEXT_LOOPS = ['none', 'pulse', 'float'], SLIDE = 0.07;\n  function hasTextAnim(an) { return !!(an && ((an.in && an.in !== 'none') || (an.out && an.out !== 'none') || (an.loop && an.loop !== 'none'))); }\n  function clip01(v) { return Math.max(0, Math.min(1, v)); }\n  function textState(an, rel, dur) {\n    var s = { alpha: 1, dy: 0, scale: 1 };\n    if (!hasTextAnim(an)) return s;\n    var inMs = an.inMs || 500, outMs = an.outMs || 500, p = clip01(rel / inMs), q = clip01((rel - (dur - outMs)) / outMs);\n    if (an.in && an.in !== 'none') {\n      var e = (1 - p) * (1 - p); s.alpha *= p;\n      if (an.in === 'slideup') s.dy += e * SLIDE; else if (an.in === 'slidedown') s.dy -= e * SLIDE; else if (an.in === 'pop') s.scale *= 0.5 + 0.5 * (1 - e);\n    }\n    if (an.out && an.out !== 'none') {\n      var e2 = q * q; s.alpha *= 1 - q;\n      if (an.out === 'slideup') s.dy -= e2 * SLIDE; else if (an.out === 'slidedown') s.dy += e2 * SLIDE; else if (an.out === 'pop') s.scale *= 1 - 0.3 * e2;\n    }\n    if (an.loop === 'pulse') s.scale *= 1 + 0.04 * Math.sin(2 * Math.PI * rel / 1200);\n    else if (an.loop === 'float') s.dy += 0.012 * Math.sin(2 * Math.PI * rel / 2000);\n    return s;\n  }\n  var TITLE_POS = { top: 0.07, center: 0.40, bottom: 0.76 };\n  // The point of a title (in pixels down the picture) that it grows and shrinks about: about the middle of its first line.\n  function textAnchorY(t, H) { var pos = TITLE_POS[t.pos]; if (pos == null) pos = TITLE_POS.bottom; return pos * H + ((t.size || 7) / 100 * H) * 0.6; }\n  // ffmpeg expressions (in t, seconds since the video part started) for the same motion. a = when the title appears, d = how long it shows, both in seconds\n  // from the start of the part (a can be negative: the title began earlier). Returns { fades: [filters], scale: expr | null, dy: expr | null }.\n  function textExprs(an, a, d) {\n    var inS = (an.inMs || 500) / 1000, outS = (an.outMs || 500) / 1000, f = function (n) { return String(Math.round(n * 10000) / 10000); };\n    var P = 'clip((t-(' + f(a) + '))/' + f(inS) + ',0,1)', Q = 'clip((t-(' + f(a) + ')-(' + f(d - outS) + '))/' + f(outS) + ',0,1)', fades = [], S = [], DY = [];\n    if (an.in && an.in !== 'none') {\n      if (a + inS > 0) fades.push('fade=t=in:st=' + f(Math.max(0, a)) + ':d=' + f(Math.max(0.05, a + inS - Math.max(0, a))) + ':alpha=1');\n      if (an.in === 'slideup') DY.push('+pow(1-' + P + ',2)*' + SLIDE); else if (an.in === 'slidedown') DY.push('-pow(1-' + P + ',2)*' + SLIDE);\n      else if (an.in === 'pop') S.push('(0.5+0.5*(1-pow(1-' + P + ',2)))');\n    }\n    if (an.out && an.out !== 'none') {\n      fades.push('fade=t=out:st=' + f(a + d - outS) + ':d=' + f(outS) + ':alpha=1');\n      if (an.out === 'slideup') DY.push('-pow(' + Q + ',2)*' + SLIDE); else if (an.out === 'slidedown') DY.push('+pow(' + Q + ',2)*' + SLIDE);\n      else if (an.out === 'pop') S.push('(1-0.3*pow(' + Q + ',2))');\n    }\n    if (an.loop === 'pulse') S.push('(1+0.04*sin(2*PI*(t-(' + f(a) + '))/1.2))'); else if (an.loop === 'float') DY.push('+0.012*sin(2*PI*(t-(' + f(a) + '))/2)');\n    return { fades: fades, scale: S.length ? S.join('*') : null, dy: DY.length ? '(0' + DY.join('') + ')' : null };\n  }\n\n  var api = { TEXT_IN_OUT: TEXT_IN_OUT, TEXT_LOOPS: TEXT_LOOPS, hasTextAnim: hasTextAnim, textState: textState, textAnchorY: textAnchorY, textExprs: textExprs, OVERLAY: OVERLAY, PICTURE: PICTURE, RANGE: RANGE, kfValue: kfValue, valueOf: valueOf, overlayState: overlayState, pictureTransform: pictureTransform,\n    spanAt: spanAt, overlayRect: overlayRect, shiftKf: shiftKf, kfExpr: kfExpr };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  if (typeof window !== 'undefined') { window.NakiAnim = api; window.NakiVersions = window.NakiVersions || {}; window.NakiVersions['anim.js'] = 'text-anim'; }\n  return api;\n})();\n","look2Js":"'use strict';\n/* Naki look, part two: the extra Adjust sliders (highlights, shadows, tint, hue, grain) and the video effects (shake, glitch, blur, flash, RGB split,\n   film grain). Pure helpers shared by the editor preview and the ffmpeg export engine. The fast export engine does not draw any of these: a project\n   that uses one is handed to the ffmpeg engine, the same as speed changes. Each slider value is stored from -1 to 1 (grain 0 to 1). */\nvar NakiLook2 = (function () {\n  var EXTRA = { highlights: [-1, 1], shadows: [-1, 1], tint: [-1, 1], hue: [-1, 1], grain: [0, 1] };\n  var FX = [\n    { key: 'shake', label: 'Shake' }, { key: 'glitch', label: 'Glitch' }, { key: 'blur', label: 'Blur' },\n    { key: 'flash', label: 'Flash' }, { key: 'rgbsplit', label: 'RGB split' }, { key: 'grain', label: 'Film grain' }\n  ];\n  function fxLabel(key) { for (var i = 0; i < FX.length; i++) if (FX[i].key === key) return FX[i].label; return key; }\n  function hasExtras(f) { return !!f && Object.keys(EXTRA).some(function (k) { return +f[k] > 0.0005 || +f[k] < -0.0005; }); }\n  function f2(n) { return String(Math.round(n * 1000) / 1000); }\n  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }\n  // The two points of the tone curve that shadows and highlights move (at a quarter and three quarters of the way up).\n  function curvePoints(f) { return [clamp(0.25 + 0.18 * (+f.shadows || 0), 0.02, 0.48), clamp(0.75 + 0.18 * (+f.highlights || 0), 0.52, 0.98)]; }\n\n  // ffmpeg: the filters for the extra sliders, in order.\n  function ffmpegAdjust(f) {\n    var out = [];\n    if (!f) return out;\n    if (+f.hue) out.push('hue=h=' + f2(f.hue * 180));\n    if (+f.tint) out.push('colorbalance=gm=' + f2(-0.3 * f.tint) + ':gh=' + f2(-0.15 * f.tint));\n    if (+f.shadows || +f.highlights) { var c = curvePoints(f); out.push(\"curves=all='0/0 0.25/\" + f2(c[0]) + ' 0.75/' + f2(c[1]) + \" 1/1'\"); }\n    if (+f.grain) out.push('noise=alls=' + Math.round(f.grain * 35) + ':allf=t');\n    return out;\n  }\n  // The editor preview: a table for the SVG tone curve, a CSS hue turn, the colour of the tint layer, and the strength of the grain layer.\n  function previewTone(f) { var c = f && (+f.shadows || +f.highlights) ? curvePoints(f) : [0.25, 0.75]; return [0, c[0], 0.5, c[1], 1]; }\n  function previewHue(f) { return f && +f.hue ? 'hue-rotate(' + f2(f.hue * 180) + 'deg)' : ''; }\n  function previewTint(f) {\n    var t = f ? +f.tint || 0 : 0; if (!t) return '';\n    return t > 0 ? 'rgb(255,' + Math.round(255 - 70 * t) + ',255)' : 'rgb(' + Math.round(255 + 50 * t) + ',255,' + Math.round(255 + 50 * t) + ')';\n  }\n  function previewGrain(f) { return f && +f.grain ? 0.4 * f.grain : 0; }\n\n  // ffmpeg: one video effect over a stretch of the part, from a to b seconds after the part starts. Reads cur, writes out. W, H = picture size.\n  function ffmpegFx(x, a, b, cur, out, W, H) {\n    var s = x.strength == null ? 0.5 : x.strength, en = \"enable='between(t,\" + a.toFixed(3) + ',' + b.toFixed(3) + \")'\", I = '[' + cur + ']', O = '[' + out + ']';\n    switch (x.fx) {\n      case 'blur': return I + 'gblur=sigma=' + f2(2 + 18 * s) + ':' + en + O;\n      case 'flash': return I + \"eq=brightness='\" + f2(0.1 + 0.9 * s) + '*max(0,1-(t-' + a.toFixed(3) + ')/' + Math.max(0.05, Math.min(b - a, 0.35)).toFixed(3) + \")':eval=frame:\" + en + O;\n      case 'rgbsplit': { var d = Math.round(3 + 10 * s); return I + 'rgbashift=rh=' + (-d) + ':bh=' + d + ':' + en + O; }\n      case 'glitch': { var g = Math.round(8 + 18 * s); return I + 'rgbashift=rh=' + (-g) + ':bh=' + g + ':gv=' + Math.round(4 + 8 * s) + \":enable='between(t,\" + a.toFixed(3) + ',' + b.toFixed(3) + \")*lt(mod(n,8),3)'\" + O; }\n      case 'grain': return I + 'noise=alls=' + Math.round(10 + 40 * s) + ':allf=t:' + en + O;\n      case 'shake': {\n        var sw = Math.round(W * 1.08 / 2) * 2, sh = Math.round(H * 1.08 / 2) * 2, A = Math.max(1, Math.round(W * 0.03 * s * 2)), id = out;\n        return I + 'split[' + id + 'a][' + id + 'b];[' + id + 'b]scale=' + sw + ':' + sh + ',crop=' + W + ':' + H + \":x='(in_w-\" + W + \")/2+\" + A + \"*sin(47*t)':y='(in_h-\" + H + \")/2+\" + A + \"*cos(53*t)'[\" + id + 's];[' + id + 'a][' + id + 's]overlay=' + en + O;\n      }\n    }\n    return I + 'null' + O;\n  }\n  // The editor preview of the effects active at tMs: { transform, filter, flash (0-1), grain (0-1) } for the picture. x = [{ fx, strength, start, dur }].\n  function previewFx(list, tMs) {\n    var r = { transform: '', filter: '', flash: 0, grain: 0 }, t = tMs / 1000;\n    (list || []).forEach(function (x) {\n      var s = x.strength == null ? 0.5 : x.strength, rel = tMs - x.start;\n      if (x.fx === 'shake') r.transform = 'translate(' + f2(3 * s * Math.sin(47 * t)) + '%,' + f2(3 * s * Math.cos(53 * t)) + '%) scale(1.06)';\n      else if (x.fx === 'blur') r.filter += ' blur(' + f2(2 + 12 * s) + 'px)';\n      else if (x.fx === 'flash') r.flash = Math.max(r.flash, (0.1 + 0.9 * s) * Math.max(0, 1 - rel / 1000 / Math.max(0.05, Math.min(x.dur / 1000, 0.35))));\n      else if (x.fx === 'rgbsplit') { var d = f2(1 + 4 * s); r.filter += ' drop-shadow(-' + d + 'px 0 0 rgba(255,0,0,.6)) drop-shadow(' + d + 'px 0 0 rgba(0,200,255,.6))'; }\n      else if (x.fx === 'glitch') { if (Math.floor(t * 30) % 8 < 3) { var g = f2(3 + 7 * s); r.filter += ' drop-shadow(-' + g + 'px 0 0 rgba(255,0,0,.7)) drop-shadow(' + g + 'px 0 0 rgba(0,200,255,.7))'; r.transform = 'translateX(' + f2(1.5 * s * (Math.floor(t * 30) % 2 ? 1 : -1)) + '%)'; } }\n      else if (x.fx === 'grain') r.grain = Math.max(r.grain, 0.1 + 0.5 * s);\n    });\n    return r;\n  }\n  var api = { EXTRA: EXTRA, FX: FX, fxLabel: fxLabel, hasExtras: hasExtras, curvePoints: curvePoints, ffmpegAdjust: ffmpegAdjust, previewTone: previewTone, previewHue: previewHue,\n    previewTint: previewTint, previewGrain: previewGrain, ffmpegFx: ffmpegFx, previewFx: previewFx };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  if (typeof window !== 'undefined') { window.NakiLook2 = api; window.NakiVersions = window.NakiVersions || {}; window.NakiVersions['look2.js'] = 'look2'; }\n  return api;\n})();\n","templatesJs":"'use strict';\n/* Naki text templates: ready-made looks for a title (size, colour, place, font, outline, shadow, box) together with how it comes and goes.\n   A template is only a set of the settings a text already has, so it works in the preview and in both export engines. */\nvar NakiTemplates = (function () {\n  var LIST = [\n    { key: 'clean', label: 'Clean', text: 'Your text', style: { size: 7, color: '#ffffff', pos: 'bottom', weight: 700, bg: false, font: 'sans', outline: 0, shadow: 1 }, anim: { in: 'fade', out: 'fade', loop: 'none', inMs: 400, outMs: 400 } },\n    { key: 'headline', label: 'Headline', text: 'BIG NEWS', style: { size: 12, color: '#ffd400', pos: 'center', weight: 800, bg: false, font: 'bold', outline: 0.6, shadow: 1 }, anim: { in: 'pop', out: 'fade', loop: 'none', inMs: 450, outMs: 400 } },\n    { key: 'lower', label: 'Lower third', text: 'Name here', style: { size: 5, color: '#ffffff', pos: 'bottom', weight: 700, bg: true, font: 'sans', outline: 0, shadow: 0 }, anim: { in: 'slideup', out: 'slidedown', loop: 'none', inMs: 450, outMs: 450 } },\n    { key: 'neon', label: 'Neon', text: 'Neon', style: { size: 9, color: '#00f0ff', pos: 'center', weight: 700, bg: false, font: 'sans', outline: 0.3, shadow: 1 }, anim: { in: 'fade', out: 'fade', loop: 'pulse', inMs: 500, outMs: 500 } },\n    { key: 'comic', label: 'Comic', text: 'WOW!', style: { size: 11, color: '#ffffff', pos: 'center', weight: 800, bg: false, font: 'script', outline: 0.8, shadow: 1 }, anim: { in: 'pop', out: 'pop', loop: 'none', inMs: 350, outMs: 350 } },\n    { key: 'quote', label: 'Quote', text: 'A quiet line', style: { size: 6, color: '#f5f0e6', pos: 'center', weight: 400, bg: false, font: 'serif', outline: 0, shadow: 1 }, anim: { in: 'fade', out: 'fade', loop: 'none', inMs: 900, outMs: 900 } },\n    { key: 'code', label: 'Terminal', text: '> hello', style: { size: 6, color: '#9dff9d', pos: 'bottom', weight: 700, bg: true, font: 'mono', outline: 0, shadow: 0 }, anim: { in: 'slideup', out: 'fade', loop: 'none', inMs: 400, outMs: 400 } },\n    { key: 'impact', label: 'Impact', text: 'IMPACT', style: { size: 14, color: '#ffffff', pos: 'top', weight: 800, bg: false, font: 'bold', outline: 1, shadow: 1 }, anim: { in: 'pop', out: 'pop', loop: 'none', inMs: 300, outMs: 300 } },\n    { key: 'subtitle', label: 'Subtitle', text: 'Subtitle', style: { size: 5, color: '#ffffff', pos: 'bottom', weight: 700, bg: true, font: 'sans', outline: 0, shadow: 0 }, anim: { in: 'fade', out: 'fade', loop: 'none', inMs: 250, outMs: 250 } },\n    { key: 'float', label: 'Float', text: 'Floating', style: { size: 8, color: '#ffb3d9', pos: 'center', weight: 700, bg: false, font: 'sans', outline: 0.2, shadow: 1 }, anim: { in: 'slidedown', out: 'fade', loop: 'float', inMs: 600, outMs: 500 } }\n  ];\n  function find(key) { for (var i = 0; i < LIST.length; i++) if (LIST[i].key === key) return LIST[i]; return null; }\n  var api = { LIST: LIST, find: find };\n  if (typeof module !== 'undefined' && module.exports) module.exports = api;\n  if (typeof window !== 'undefined') { window.NakiTemplates = api; window.NakiVersions = window.NakiVersions || {}; window.NakiVersions['templates.js'] = 'look2'; }\n  return api;\n})();\n","test":"'use strict';\n// node tests/look.test.js\n// Text animations and templates, the extra Adjust sliders (highlights, shadows, tint, hue, grain) and the video effects (shake, glitch, blur, flash, RGB split, film grain).\nconst assert = require('assert'), cp = require('child_process'), fs = require('fs'), os = require('os'), path = require('path');\nconst A = require('../www/anim.js'), L = require('../www/look2.js'), T = require('../www/templates.js'), P = require('../www/project.js'), NP = require('../www/plan.js'), E = require('../www/export-engine.js');\nconst { WebCodecsExport } = require('../www/webcodecs-export.js');\nlet n = 0; const ok = (name, fn) => { fn(); n++; console.log('  ok  ' + name); };\nconst near = (a, b, tol, m) => assert(Math.abs(a - b) <= (tol == null ? 1e-6 : tol), (m || '') + ' ' + a + ' vs ' + b);\n\n// ---------- text animation maths ----------\nok('text animation: comes in, stays, goes out; pop grows, slide moves, pulse and float keep going', () => {\n  const an = { in: 'pop', out: 'fade', loop: 'none', inMs: 500, outMs: 500 };\n  let s = A.textState(an, 0, 3000); near(s.alpha, 0); near(s.scale, 0.5);\n  s = A.textState(an, 250, 3000); near(s.alpha, 0.5); near(s.scale, 0.875);\n  s = A.textState(an, 1500, 3000); assert.deepStrictEqual(s, { alpha: 1, dy: 0, scale: 1 });\n  s = A.textState(an, 2750, 3000); near(s.alpha, 0.5); near(A.textState(an, 3000, 3000).alpha, 0);\n  s = A.textState({ in: 'slideup', out: 'slidedown', inMs: 500, outMs: 500 }, 0, 3000); near(s.dy, 0.07); near(A.textState({ in: 'slideup', inMs: 500 }, 500, 3000).dy, 0);\n  assert(A.textState({ in: 'slidedown', inMs: 500 }, 100, 3000).dy < 0); near(A.textState({ in: 'none', out: 'slidedown', outMs: 500 }, 3000, 3000).dy, 0.07);\n  near(A.textState({ loop: 'pulse' }, 300, 3000).scale, 1.04); near(A.textState({ loop: 'float' }, 500, 3000).dy, 0.012);\n  assert.deepStrictEqual(A.textState(null, 100, 1000), { alpha: 1, dy: 0, scale: 1 }); assert.strictEqual(A.hasTextAnim({ in: 'none', out: 'none', loop: 'none' }), false);\n  near(A.textAnchorY({ pos: 'bottom', size: 7 }, 1280), 1026.56, 0.01); assert(A.textAnchorY({ pos: 'top', size: 7 }, 1280) < A.textAnchorY({ pos: 'center', size: 7 }, 1280));\n});\nok('text animation: the ffmpeg expressions match the maths', () => {\n  const ex = A.textExprs({ in: 'pop', out: 'fade', loop: 'pulse', inMs: 500, outMs: 500 }, 1, 3);\n  assert.deepStrictEqual(ex.fades, ['fade=t=in:st=1:d=0.5:alpha=1', 'fade=t=out:st=3.5:d=0.5:alpha=1']); assert(ex.scale.includes('pow(1-clip((t-(1))/0.5,0,1),2)') && ex.scale.includes('sin(2*PI*(t-(1))/1.2)') && ex.dy === null, ex.scale);\n  const sl = A.textExprs({ in: 'slideup', out: 'slidedown', loop: 'float', inMs: 400, outMs: 400 }, 0, 2); assert.strictEqual(sl.scale, null); assert(sl.dy.startsWith('(0+pow(1-') && sl.dy.includes('+0.012*sin('), sl.dy);\n  const early = A.textExprs({ in: 'fade', inMs: 500 }, -2, 6); assert.deepStrictEqual(early.fades, [], 'a title that came in long before this part needs no fade in');\n  const part = A.textExprs({ in: 'fade', inMs: 500 }, -0.2, 6); assert.strictEqual(part.fades.length, 1, 'half way through the fade in when this part starts');\n});\n\n// ---------- templates ----------\nconst mk = () => ({ naki: 'project', version: 1, fps: 30, durationMs: 12000, levels: [], assets: { movie: { type: 'video', durMs: 100000 } },\n  tracks: [{ id: 't-movie', kind: 'video', role: 'movie', muted: false, hidden: false, volume: 1, locked: false, clips: [{ id: 'vA', type: 'video', asset: 'movie', start: 0, dur: 12000, in: 10000, speed: 1, volume: 1, fadeIn: 0, fadeOut: 0, link: 'lA' }] }] });\nconst base = mk();\nok('templates: ten looks, each made only of settings a text really has, so applying one gives exactly that look', () => {\n  assert.strictEqual(T.LIST.length, 10);\n  T.LIST.forEach(tp => {\n    const out = {}; let p = P.addTextClip(base, 1000, 3000, out); p = P.setTextProps(p, out.id, Object.assign({ text: tp.text }, tp.style)); p = P.setTextAnim(p, out.id, tp.anim);\n    const c = P.findClip(p, out.id).clip;\n    assert.strictEqual(c.text, tp.text); assert.strictEqual(c.size, tp.style.size, tp.key + ' size'); assert.strictEqual(c.color, tp.style.color); assert.strictEqual(c.pos, tp.style.pos); assert.strictEqual(!!c.bg, tp.style.bg);\n    assert.strictEqual(c.font || 'sans', tp.style.font, tp.key + ' font'); assert.strictEqual(c.outline || 0, tp.style.outline, tp.key + ' outline'); assert.strictEqual(c.shadow == null ? 1 : c.shadow, tp.style.shadow, tp.key + ' shadow');\n    assert.strictEqual(c.anim.in, tp.anim.in); assert.strictEqual(c.anim.loop, tp.anim.loop, tp.key); assert(A.hasTextAnim(c.anim), tp.key + ' animates');\n  });\n  assert.strictEqual(T.find('neon').anim.loop, 'pulse'); assert.strictEqual(T.find('nope'), null);\n});\n\n// ---------- project: text animation ----------\nok('text animation: set on a text, kept within range, cleared when nothing moves, and a split keeps each end right', () => {\n  const o = {}; let p = P.addTextClip(base, 1000, 3000, o), id = o.id;\n  const a = P.setTextAnim(p, id, { in: 'pop', out: 'fade', inMs: 700 }); assert.deepStrictEqual(P.findClip(a, id).clip.anim, { in: 'pop', out: 'fade', loop: 'none', inMs: 700, outMs: 500 }); assert.strictEqual(P.findClip(p, id).clip.anim, undefined);\n  assert.strictEqual(P.findClip(P.setTextAnim(a, id, { inMs: 99999 }), id).clip.anim.inMs, 1500, 'never more than half the text'); assert.strictEqual(P.findClip(P.setTextAnim(a, id, { inMs: 5 }), id).clip.anim.inMs, 100);\n  assert.strictEqual(P.setTextAnim(a, id, { in: 'sparkle' }), a, 'an unknown kind is ignored'); assert.strictEqual(P.setTextAnim(a, id, { in: 'pop' }), a, 'no change: the same project');\n  assert.strictEqual(P.findClip(P.setTextAnim(P.setTextAnim(a, id, { in: 'none' }), id, { out: 'none' }), id).clip.anim, undefined, 'all none: nothing stored');\n  assert.strictEqual(P.setTextAnim(base, 'vA', { in: 'pop' }), base, 'only text');\n  const st = {}; const stk = P.addSticker ? P.addSticker(base, 0, 2000, '*', st) : base; if (P.addSticker) assert.strictEqual(P.setTextAnim(stk, st.id, { in: 'pop' }), stk, 'not stickers');\n  const sp = P.splitAt(P.setTextAnim(p, id, { in: 'pop', out: 'fade' }), 2500), cs = sp.tracks.find(t => t.id === 't-text').clips;\n  assert.strictEqual(cs.length, 2); assert.deepStrictEqual([cs[0].anim.in, cs[0].anim.out, cs[1].anim.in, cs[1].anim.out], ['pop', 'none', 'none', 'fade'], 'the first piece keeps how it comes in, the second how it goes out');\n});\n\n// ---------- project: extra Adjust sliders ----------\nok('adjust: highlights, shadows, tint, hue and grain are kept within range, and a zero is not stored', () => {\n  const a = P.setFilter(base, 'vA', { hue: 0.5, shadows: 0.4, grain: 3, tint: -9 }), f = P.findClip(a, 'vA').clip.filter;\n  assert.deepStrictEqual([f.hue, f.shadows, f.grain, f.tint], [0.5, 0.4, 1, -1]); assert.strictEqual(f.highlights, undefined);\n  assert.strictEqual(P.findClip(P.setFilter(a, 'vA', { hue: 0, shadows: 0, grain: 0, tint: 0 }), 'vA').clip.filter, undefined, 'all back to normal removes the filter');\n  const h = P.setFilter(base, 'vA', { highlights: -0.3 }); assert.strictEqual(P.findClip(h, 'vA').clip.filter.highlights, -0.3, 'one alone is not lost');\n  assert.strictEqual(P.findClip(P.setFilter(a, 'vA', { warmth: 0.2 }), 'vA').clip.filter.hue, 0.5, 'and does not disturb the older ones');\n  const plan = NP.projectToPlan(a).video[0].filter; assert.deepStrictEqual([plan.hue, plan.shadows, plan.grain, plan.tint], [0.5, 0.4, 1, -1], 'the plan carries them');\n  assert.strictEqual(L.hasExtras(plan), true); assert.strictEqual(L.hasExtras({ brightness: 1, warmth: 0.3 }), false); assert.strictEqual(L.hasExtras(null), false);\n  assert.strictEqual(WebCodecsExport.canRender({ durationMs: 1000, video: [{ type: 'play', filter: plan }], audio: [] }), false, 'the fast engine leaves them to ffmpeg');\n});\n\n// ---------- project: video effects ----------\nok('effects: an effect at the playhead with a strength; overlapping ones get their own row; an empty row goes away; the plan lists them', () => {\n  const o1 = {}, o2 = {}; let p = P.addFx(base, 1000, 'shake', o1); assert.deepStrictEqual(P.validate(p), []);\n  const c = P.findClip(p, o1.id).clip, tr = P.findClip(p, o1.id).track; assert.deepStrictEqual([c.fx, c.start, c.dur, c.strength, tr.kind, tr.role], ['shake', 1000, 2000, 0.5, 'fx', 'fx']);\n  assert.strictEqual(P.addFx(base, 1000, 'flash', {}).tracks.find(t => t.kind === 'fx').clips[0].dur, 500, 'a flash is short'); assert.strictEqual(P.addFx(base, 0, 'nope', {}), base);\n  p = P.addFx(p, 2000, 'blur', o2); assert.strictEqual(p.tracks.filter(t => t.kind === 'fx').length, 2, 'overlapping in time: a second row');\n  assert.deepStrictEqual(P.fxAt(p, 2500).map(x => x.fx).sort(), ['blur', 'shake']); assert.strictEqual(P.fxAt(p, 100).length, 0); assert.strictEqual(P.fxAt(p, 100).length, 0);\n  const s = P.setFxProps(p, o1.id, { strength: 9, fx: 'glitch' }), sc = P.findClip(s, o1.id).clip; assert.deepStrictEqual([sc.fx, sc.strength], ['glitch', 1]); assert.strictEqual(P.setFxProps(p, o1.id, {}), p); assert.strictEqual(P.setFxProps(p, 'vA', { strength: 1 }), p);\n  const del = P.deleteClip(P.deleteClip(p, o2.id), o1.id); assert.strictEqual(del.tracks.filter(t => t.kind === 'fx').length, 0, 'the empty row is gone');\n  const ids = P.addFx(del, 0, 'blur', {}).tracks.map(t => t.id); assert.strictEqual(new Set(ids).size, ids.length);\n  const plan = NP.projectToPlan(p); assert.deepStrictEqual(plan.fx.map(x => [x.startMs, x.durMs, x.fx, x.strength]), [[1000, 2000, 'shake', 0.5], [2000, 2000, 'blur', 0.5]]); assert.strictEqual(NP.projectToPlan(base).fx, undefined);\n  assert.strictEqual(WebCodecsExport.canRender(plan), false, 'effects are made by the ffmpeg engine');\n  const fz = P.insertFreeze ? P.insertFreeze(p, 1500, 1000) : p; if (P.insertFreeze) assert.strictEqual(P.findClip(fz, o1.id).clip.dur, 3000, 'a held picture keeps the effect on');\n  const pt = NP.projectToPlan(P.setTextAnim(P.addTextClip(base, 0, 3000, o1) && P.setTextAnim(P.addTextClip(base, 0, 3000, o2), o2.id, { in: 'fade', loop: 'pulse' }), o2.id, {})).texts; assert(pt[0].anim && pt[0].anim.loop === 'pulse', 'the plan carries the text animation');\n});\n\n// ---------- the ffmpeg engine ----------\nconst info0 = { hasAudio: false, audioMono: false, width: 640, height: 360, sar: 1, durationSec: 6 };\nconst plan0 = (extra, spanA) => Object.assign({ naki: 'export-plan', version: 2, durationMs: 4000, movie: { durationMs: 6000 }, audio: [],\n  video: [Object.assign({ type: 'play', sessionStart: 0, sessionEnd: 4000, movieStart: 0 }, spanA || {})] }, extra || {});\nconst argsFor = (r, f) => r.jobs.find(j => j.produces === f).args, graph = (a) => a[a.indexOf('-filter_complex') + 1];\nok('ffmpeg engine: a title that moves becomes its own looped picture with expressions; a still title is unchanged', () => {\n  const t0 = { startMs: 500, durMs: 2000, text: 'Hi', size: 7, pos: 'bottom' };\n  const still = E.planToJobs(plan0({ texts: [t0] }), info0, { height: 360 }), s = argsFor(still, 'v0000.ts'); assert(graph(s).includes(\"overlay=0:0:enable='between(t,0.500,2.500)'\") && !s.join(' ').includes('-loop'), graph(s));\n  const mov = E.planToJobs(plan0({ texts: [Object.assign({ anim: { in: 'pop', out: 'fade', loop: 'none', inMs: 500, outMs: 500 } }, t0)] }), info0, { height: 360 }), m = argsFor(mov, 'v0000.ts'), g = graph(m);\n  assert(m.join(' ').includes('-loop 1 -framerate 30 -t 2.000 -i txt000.png'), m.join(' ')); assert(g.includes('setpts=PTS-STARTPTS+0.500/TB,format=rgba,fade=t=in:st=0.5:d=0.5:alpha=1,fade=t=out:st=2:d=0.5:alpha=1,scale=w=\\'trunc(iw*('), g);\n  assert(g.includes(\"overlay=x='(main_w-overlay_w)/2':y='\"), g); assert(g.includes('eof_action=pass:enable=\\'between(t,0.500,2.500)\\''), g);\n});\nok('ffmpeg engine: effects and the extra Adjust sliders become filters, only where they apply', () => {\n  const fx = [{ startMs: 1000, durMs: 1000, fx: 'blur', strength: 0.5 }, { startMs: 1500, durMs: 1000, fx: 'shake', strength: 1 }, { startMs: 3000, durMs: 500, fx: 'flash', strength: 1 }];\n  const r = E.planToJobs(plan0({ fx }), info0, { height: 360 }), g = graph(argsFor(r, 'v0000.ts'));\n  assert(g.includes(\"gblur=sigma=11:enable='between(t,1.000,2.000)'\") && g.includes('split[') && g.includes(\"overlay=enable='between(t,1.500,2.500)'\") && g.includes(\"eq=brightness='1*max(0,1-(t-3.000)/0.350)':eval=frame\"), g);\n  const none = E.planToJobs(plan0(), info0, { height: 360 }); assert(argsFor(none, 'v0000.ts').indexOf('-filter_complex') < 0, 'no effect: the plain command');\n  const adj = E.planToJobs(plan0(null, { filter: { brightness: 1, contrast: 1, saturate: 1, hue: 0.5, shadows: 0.5, grain: 0.4, tint: 0.3 } }), info0, { height: 360 }), ga = graph(argsFor(adj, 'v0000.ts'));\n  assert(ga.includes('hue=h=90,colorbalance=gm=-0.09:gh=-0.045,curves=all=\\'0/0 0.25/0.34 0.75/0.75 1/1\\',noise=alls=14:allf=t'), ga);\n});\n// ---- real ffmpeg, only when this computer has a recent one ----\nfunction ffmpegOk() { const r = cp.spawnSync('ffmpeg', ['-version'], { encoding: 'utf8' }); const m = r.status === 0 && /version\\s+n?(\\d+)/.exec(r.stdout); return !!m && +m[1] >= 5; }\nif (ffmpegOk()) {\n  const render = (plan, opts, png, grey) => {\n    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'naki-look-')), sh = (a) => cp.spawnSync('ffmpeg', ['-y', '-v', 'error'].concat(a), { cwd: dir, encoding: 'utf8' });\n    let r = grey ? sh(['-f', 'lavfi', '-i', 'color=c=' + grey + ':s=640x360:r=30:d=6', '-pix_fmt', 'yuv420p', '-t', '6', 'm.mp4']) : sh(['-f', 'lavfi', '-i', 'color=c=red:s=320x360:r=30:d=6', '-f', 'lavfi', '-i', 'color=c=blue:s=320x360:r=30:d=6', '-filter_complex', '[0:v][1:v]hstack,format=yuv420p', '-t', '6', 'm.mp4']); assert.strictEqual(r.status, 0, r.stderr);\n    fs.renameSync(path.join(dir, 'm.mp4'), path.join(dir, 'movie.in'));\n    const built = E.planToJobs(plan, info0, Object.assign({ height: 360 }, opts || {}));\n    built.textFiles.forEach(t => { const bx = Math.round(t.width / 2 - 40), by = Math.round(A.textAnchorY(t.clip, t.height) - 15); const x = sh(['-f', 'lavfi', '-i', 'color=c=white@1:s=80x30,format=rgba', '-vf', 'pad=' + t.width + ':' + t.height + ':' + bx + ':' + by + ':color=black@0', '-frames:v', '1', t.name]); assert.strictEqual(x.status, 0, x.stderr); });\n    built.jobs.forEach(j => { const x = sh(j.args); assert.strictEqual(x.status, 0, j.label + ': ' + x.stderr); });\n    fs.writeFileSync(path.join(dir, 'video.txt'), built.videoList.map(f => \"file '\" + f + \"'\\n\").join(''));\n    r = sh(E.finalMixArgs([], plan.durationMs)); assert.strictEqual(r.status, 0, r.stderr);\n    const frame = (t) => { const o = cp.spawnSync('ffmpeg', ['-v', 'error', '-ss', String(t), '-i', path.join(dir, 'out.mp4'), '-frames:v', '1', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-'], { encoding: null }); return { w: built.width, h: built.height, d: o.stdout }; };\n    const px = (t, fx, fy) => { const f = frame(t), i = (Math.round(fy * f.h) * f.w + Math.round(fx * f.w)) * 3; return [f.d[i], f.d[i + 1], f.d[i + 2]]; };\n    const whiteBox = (t) => { const f = frame(t); let c = 0, x0 = 1e9, x1 = -1, y0 = 1e9, y1 = -1; for (let y = 0; y < f.h; y++) for (let x = 0; x < f.w; x++) { const i = (y * f.w + x) * 3; if (f.d[i + 1] > 60) { c++; x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); } } return { n: c, x0, x1, y0, y1, cy: (y0 + y1) / 2, w: x1 - x0 + 1, h: y1 - y0 + 1 }; };\n    const same = (t1, t2) => { const a = frame(t1).d, b = frame(t2).d; let d = 0; for (let i = 0; i < a.length; i += 7) d += Math.abs(a[i] - b[i]); return d; };\n    const frames = +cp.spawnSync('ffprobe', ['-v', 'error', '-count_frames', '-select_streams', 'v:0', '-show_entries', 'stream=nb_read_frames', '-of', 'csv=p=0', path.join(dir, 'out.mp4')], { encoding: 'utf8' }).stdout.trim().split('\\n')[0];\n    return { px, whiteBox, same, frames, frame, done: () => fs.rmSync(dir, { recursive: true, force: true }) };\n  };\n  const title = (anim) => ({ startMs: 1000, durMs: 2000, text: 'Hi', size: 7, pos: 'bottom', anim });\n  ok('real ffmpeg: a title fades in and out as the maths says', () => {\n    const an = { in: 'fade', out: 'fade', loop: 'none', inMs: 500, outMs: 500 }, r = render(plan0({ texts: [title(an)] }));\n    try {\n      assert.strictEqual(r.frames, 120); const ay = A.textAnchorY({ pos: 'bottom', size: 7 }, 360) / 360;\n      assert(r.whiteBox(0.5).n === 0, 'not yet there'); // the box is white over red, so the red channel stays high: read the green one\n      const g = (t) => r.px(t, 0.5, ay)[1]; assert(Math.abs(g(1.25) - A.textState(an, 250, 2000).alpha * 255) < 60, 'half way in: ' + g(1.25)); assert(g(2.0) > 230, 'fully there: ' + g(2.0)); assert(g(2.75) < 130 && g(2.75) > 20, 'going out: ' + g(2.75)); assert(g(3.5) < 30, 'gone: ' + g(3.5));\n    } finally { r.done(); }\n  });\n  ok('real ffmpeg: a title slides, pops and floats as the maths says', () => {\n    const slide = { in: 'slideup', out: 'none', loop: 'none', inMs: 600, outMs: 500 }, r = render(plan0({ texts: [title(slide)] }));\n    try {\n      const a = r.whiteBox(1.3), b = r.whiteBox(2.0), want = A.textState(slide, 300, 2000).dy * 360;\n      assert(a.n > 0 && b.n > 0, 'visible: ' + JSON.stringify(a)); assert(a.cy > b.cy + 3, 'starts lower and slides up: ' + a.cy + ' -> ' + b.cy); near(a.cy - b.cy, want, 5, 'the distance the maths gives');\n    } finally { r.done(); }\n    const pop = { in: 'pop', out: 'none', loop: 'none', inMs: 600, outMs: 500 }, p = render(plan0({ texts: [title(pop)] }));\n    try { const a = p.whiteBox(1.3), b = p.whiteBox(2.0); assert(a.n > 0 && a.w < b.w * 0.95, 'smaller at first: ' + a.w + ' -> ' + b.w); near(b.w, 80, 3, 'then full size'); near(a.w / b.w, A.textState(pop, 300, 2000).scale, 0.08, 'the size the maths gives'); } finally { p.done(); }\n    const fl = { in: 'none', out: 'none', loop: 'float', inMs: 500, outMs: 500 }, f = render(plan0({ texts: [title(fl)] }));\n    try { const a = f.whiteBox(1.5), b = f.whiteBox(2.5); assert(a.n > 0 && b.n > 0 && Math.abs(a.cy - b.cy) >= 4, 'it drifts up and down: ' + a.cy + ' / ' + b.cy); } finally { f.done(); }\n  });\n  ok('real ffmpeg: the extra Adjust sliders change the picture the way they should', () => {\n    const f = (o) => Object.assign({ brightness: 1, contrast: 1, saturate: 1 }, o), grey = (o, c) => render(plan0(null, { filter: f(o) }), null, null, c);\n    const base0 = render(plan0()), hue = render(plan0(null, { filter: f({ hue: 0.667 }) }));\n    try { const r0 = base0.px(1, 0.25, 0.5), r1 = hue.px(1, 0.25, 0.5); assert(r0[0] > 180 && r0[1] < 80, 'red: ' + r0); assert(r1[1] > r1[0] + 40, 'a third of the way round the colour wheel: red became ' + r1); } finally { base0.done(); hue.done(); }\n    const mid = grey({}, '#404040'), lift = grey({ shadows: 1 }, '#404040'), dark = grey({ shadows: -1 }, '#404040');\n    try { const m = mid.px(1, 0.5, 0.5)[0], l = lift.px(1, 0.5, 0.5)[0], d = dark.px(1, 0.5, 0.5)[0]; assert(l > m + 20 && d < m - 8, 'shadows lift and sink the dark grey: ' + d + ' < ' + m + ' < ' + l); } finally { mid.done(); lift.done(); dark.done(); }\n    const light = grey({}, '#c0c0c0'), hl = grey({ highlights: -1 }, '#c0c0c0'), hh = grey({ highlights: 1 }, '#c0c0c0');\n    try { const m = light.px(1, 0.5, 0.5)[0], l = hl.px(1, 0.5, 0.5)[0], h = hh.px(1, 0.5, 0.5)[0]; assert(l < m - 15 && h > m + 3, 'highlights pull down and push up the light grey: ' + l + ' < ' + m + ' < ' + h); } finally { light.done(); hl.done(); hh.done(); }\n    const tg = grey({ tint: -1 }, '#808080'), tm = grey({ tint: 1 }, '#808080');\n    try { const g = tg.px(1, 0.5, 0.5), m = tm.px(1, 0.5, 0.5); assert(g[1] > g[0] + 5 && m[1] < m[0] - 3, 'tint: green one way, magenta the other: ' + g + ' / ' + m); } finally { tg.done(); tm.done(); }\n    const flat = grey({}, '#808080'), grn = grey({ grain: 1 }, '#808080');\n    try { const sd = (d) => { let m = 0, c = 0, s2 = 0; for (let i = 1; i < d.length; i += 27) { m += d[i]; c++; } m /= c; for (let i = 1; i < d.length; i += 27) s2 += (d[i] - m) * (d[i] - m); return Math.sqrt(s2 / c); }; const a = sd(flat.frame(1).d), b = sd(grn.frame(1).d); assert(b > a + 5, 'grain adds noise to a flat picture: ' + a.toFixed(1) + ' -> ' + b.toFixed(1)); } finally { flat.done(); grn.done(); }\n  });\n  ok('real ffmpeg: every effect renders, only inside its time, and the video keeps its length', () => {\n    const quiet = render(plan0());\n    try {\n      const withFx = (fx, s) => render(plan0({ fx: [{ startMs: 1000, durMs: 1000, fx, strength: s == null ? 1 : s }] }));\n      let r = withFx('blur'); try { assert.strictEqual(r.frames, 120); const edgeBlur = r.px(1.5, 0.5 - 4 / 640, 0.5), edgeSharp = quiet.px(1.5, 0.5 - 4 / 640, 0.5); assert(edgeBlur[2] > edgeSharp[2] + 20, 'the red/blue edge is smeared: ' + edgeSharp + ' -> ' + edgeBlur); assert(r.same(0.5, 0.5) === 0 && r.same(2.5, 3.0) === 0, 'untouched outside'); } finally { r.done(); }\n      r = withFx('flash'); try { const a = r.px(1.02, 0.25, 0.5), b = r.px(1.7, 0.25, 0.5); assert(a[1] > 150 && b[1] < 40, 'a bright flash at the start, gone after: ' + a + ' ' + b); } finally { r.done(); }\n      r = withFx('rgbsplit'); try { assert.strictEqual(r.frames, 120); const q = quiet.px(1.5, 0.5 - 6 / 640, 0.5), s = r.px(1.5, 0.5 - 6 / 640, 0.5); assert(s[0] !== q[0] || s[2] !== q[2], 'the colours slide apart at the edge: ' + q + ' -> ' + s); } finally { r.done(); }\n      r = withFx('shake'); try { assert(r.same(1.2, 1.35) > 2000, 'the picture moves between frames'); assert(r.same(2.5, 3.0) === 0 && r.same(0.2, 0.7) === 0, 'and holds still outside'); assert.strictEqual(r.frames, 120); } finally { r.done(); }\n      r = withFx('grain'); try { assert(r.same(1.2, 1.3) > 500, 'the grain changes from frame to frame'); assert(r.same(2.5, 3.0) === 0); assert(r.frames === 120); } finally { r.done(); }\n      r = withFx('glitch'); try { assert(r.frames === 120); assert(r.same(0.2, 0.7) === 0, 'untouched outside'); } finally { r.done(); }\n      r = render(plan0({ fx: [{ startMs: 1000, durMs: 1000, fx: 'shake', strength: 1 }, { startMs: 1500, durMs: 1000, fx: 'blur', strength: 1 }] }), { ratio: '9:16', bg: { type: 'blur' } }); try { assert.strictEqual(r.frames, 120, 'two effects at once, in another shape'); } finally { r.done(); }\n      r = render(plan0({ fx: [{ startMs: 1000, durMs: 1000, fx: 'blur', strength: 0.5 }], texts: [Object.assign(title({ in: 'fade', out: 'none', loop: 'pulse', inMs: 500, outMs: 500 }), {})] }, { transitionIn: undefined })); try { assert.strictEqual(r.frames, 120, 'an effect and a moving title together'); } finally { r.done(); }\n    } finally { quiet.done(); }\n  });\n} else console.log('  --  real-file checks skipped (need ffmpeg 5 or newer on this computer)');\nconsole.log('\\n' + n + ' checks passed');\n","projectLook":"// ---------- text animation ----------\n// clip.anim = { in, out, loop, inMs, outMs } on a text clip (see anim.js). Nothing stored means no animation.\nfunction setTextAnim(p, id, patch){\n  patch = patch || {};\n  var f = findClip(p, id); if (!f || f.clip.type !== 'text' || f.clip.sticker || f.track.kind !== 'text') return p;\n  var q = cloneProject(p), c = findClip(q, id).clip, a = Object.assign({ in: 'none', out: 'none', loop: 'none', inMs: 500, outMs: 500 }, c.anim || {});\n  ['in', 'out'].forEach(function (k){ if (patch[k] !== undefined && _AN && _AN.TEXT_IN_OUT.indexOf(patch[k]) >= 0) a[k] = patch[k]; });\n  if (patch.loop !== undefined && _AN && _AN.TEXT_LOOPS.indexOf(patch.loop) >= 0) a.loop = patch.loop;\n  ['inMs', 'outMs'].forEach(function (k){ if (patch[k] !== undefined) a[k] = Math.round(Math.max(100, Math.min(2000, +patch[k] || 500))); });\n  var half = Math.max(100, Math.floor(c.dur / 2)); a.inMs = Math.min(a.inMs, half); a.outMs = Math.min(a.outMs, half);\n  if (a.in === 'none' && a.out === 'none' && a.loop === 'none') delete c.anim; else c.anim = a;\n  return JSON.stringify(q.tracks) === JSON.stringify(p.tracks) ? p : finish(q);\n}\n\n// ---------- video effects over a stretch of time ----------\n// An effect is a clip on a \"video effects\" row: shake, glitch, blur, flash, RGB split or film grain, with a strength from 0 to 1. Effects that overlap in\n// time go on separate rows (and add up).\nvar FX_KEYS = ['shake', 'glitch', 'blur', 'flash', 'rgbsplit', 'grain'];\nfunction addFx(p, t, key, out){\n  var total = p.durationMs; if (!(total > 0) || FX_KEYS.indexOf(key) < 0) return p;\n  var start = Math.max(0, Math.min(Math.round(t), total - 200)), d = Math.min(key === 'flash' ? 500 : 2000, total - start); if (d < 200) return p;\n  var q = cloneProject(p), rows = q.tracks.filter(function (x){ return x.kind === 'fx'; }), tr = null;\n  for (var i = 0; i < rows.length && !tr; i++) if (!rows[i].clips.some(function (c){ return start < clipEnd(c) && start + d > c.start; })) tr = rows[i];\n  if (!tr){\n    var k = 1; while (q.tracks.some(function (x){ return x.id === 't-fx' + k + 'v'; })) k++;\n    tr = { id: 't-fx' + k + 'v', kind: 'fx', role: 'fx', muted: false, hidden: false, volume: 1, locked: false, clips: [] }; q.tracks.push(tr);\n  }\n  var clip = { id: newId('c'), type: 'text', asset: null, start: start, dur: d, in: 0, speed: 1, fx: key, strength: 0.5 };\n  tr.clips.push(clip); if (out) out.id = clip.id;\n  return finish(q);\n}\nfunction setFxProps(p, id, patch){\n  patch = patch || {};\n  var q = cloneProject(p), f = findClip(q, id); if (!f || !f.clip.fx) return p;\n  if (patch.fx && FX_KEYS.indexOf(patch.fx) >= 0) f.clip.fx = patch.fx;\n  if (patch.strength !== undefined){ var v = +patch.strength; if (!isNaN(v)) f.clip.strength = r3(Math.max(0, Math.min(1, v))); }\n  return JSON.stringify(q.tracks) === JSON.stringify(p.tracks) ? p : finish(q);\n}\nfunction fxAt(p, t){\n  var out = [];\n  p.tracks.forEach(function (tr){ if (tr.kind !== 'fx' || tr.hidden) return; tr.clips.forEach(function (c){ if (c.start <= t && t < clipEnd(c)) out.push({ fx: c.fx, strength: c.strength, start: c.start, dur: c.dur }); }); });\n  return out;\n}\n\n","engineHelpers":"// ---- video effects, and titles that move ----\n  var fxList = plan.fx || [];\n  // One title that moves: its own looped input cut to the part, fading in / out, and placed (and grown) from expressions of the time.\n  function textAnimParts(t, sp, a, b) {\n    var a0 = (t.clip.startMs - sp.sessionStart) / 1000, d0 = t.clip.durMs / 1000, ex = _NA.textExprs(t.clip.anim, a0, d0);\n    var ay = _NA.textAnchorY(t.clip, height), f = [];\n    f.push('setpts=PTS-STARTPTS+' + a.toFixed(3) + '/TB', 'format=rgba');\n    ex.fades.forEach(function (x) { f.push(x); });\n    if (ex.scale) f.push(\"scale=w='trunc(iw*(\" + ex.scale + \")/2)*2':h='trunc(ih*(\" + ex.scale + \")/2)*2':eval=frame\");\n    return { inputs: ['-loop', '1', '-framerate', String(FPS), '-t', (b - a).toFixed(3), '-i', t.name], chain: f.join(','),\n      x: ex.scale ? '(main_w-overlay_w)/2' : '0', y: (ex.scale ? ay.toFixed(2) + '*(1-overlay_h/main_h)' : '0') + (ex.dy ? '+' + ex.dy + '*main_h' : '') };\n  }\n  \n","editorFns":"  // A filter preset puts every slider where it wants it, including the ones that came later (highlights, shadows, tint, hue, grain).\n  function presetPatch(k, a){ return Object.assign({ highlights: 0, shadows: 0, tint: 0, hue: 0, grain: 0 }, NPR['apply'](k, a)); }\n  // ----- the extra Adjust sliders in the preview -----\n  // Hue, and the tone curve (highlights and shadows), are filters on the picture; tint and grain are layers over it. Preview only: the export is exact.\n  function lookExtras(look){\n    var u = E.ui; if (!NL2 || !u.toneR) return '';\n    var tb = NL2.previewTone(look).join(' ');\n    if (E.lastTone !== tb){ u.toneR.setAttribute('tableValues', tb); u.toneG.setAttribute('tableValues', tb); u.toneB.setAttribute('tableValues', tb); E.lastTone = tb; }\n    var tint = NL2.previewTint(look), grain = NL2.previewGrain(look);\n    if (tint !== E.lastTint2){ u.tint2.style.background = tint; u.tint2.style.display = tint ? 'block' : 'none'; E.lastTint2 = tint; }\n    E.grainBase = grain;\n    return (tb !== '0 0.25 0.5 0.75 1' ? 'url(#nakiTone) ' : '') + NL2.previewHue(look) + ' ';\n  }\n  // ----- video effects: shake, glitch, blur, flash, RGB split, film grain -----\n  function syncFx(){\n    var u = E.ui; if (!NL2 || !u.fxflash || !E.proj || !E.proj.tracks) return;\n    var r = NL2.previewFx(P.fxAt(E.proj, E.t), E.t);\n    u.picbox.style.transform = r.transform; u.picbox.style.filter = r.filter.trim();\n    var fl = String(Math.round(r.flash * 1000) / 1000); if (fl !== u.fxflash._o){ u.fxflash.style.opacity = fl; u.fxflash._o = fl; }\n    var gr = String(Math.round(Math.max(r.grain, E.grainBase || 0) * 1000) / 1000); if (gr !== u.grain._o){ u.grain.style.opacity = gr; u.grain.style.display = +gr ? 'block' : 'none'; u.grain._o = gr; }\n  }\n  function selFx(){ var f = E.sel && P.findClip(E.proj, E.sel); return f && f.track.kind === 'fx' ? f.clip : null; }\n  function addFxHere(key){\n    var out = {}, q = P.addFx(E.hist.cur, Math.round(E.t), key, out);\n    if (q === E.hist.cur){ toast('There is no room for an effect at the playhead.'); return; }\n    E.sel = out.id; commit(q); openPanel('fxedit', 'fx');\n  }\n  // ----- text templates and animation -----\n  function applyTemplate(key){\n    var tp = NTPL && NTPL.find(key); if (!tp) return;\n    var c = selText(), q, id;\n    if (c){ q = P.setTextProps(E.hist.cur, c.id, tp.style); id = c.id; }\n    else {\n      var out = {}; q = P.addTextClip(E.hist.cur, Math.round(E.t), 3000, out);\n      if (q === E.hist.cur){ toast('There is no room for text at the playhead. Move it or shorten the other text.'); return; }\n      id = out.id; q = P.setTextProps(q, id, Object.assign({ text: tp.text }, tp.style));\n    }\n    q = P.setTextAnim(q, id, tp.anim); E.sel = id; commit(q);\n  }\n","editorPanels":"    templates: { title: 'Text templates', build: function (body){\n      body.appendChild(chips(NTPL ? NTPL.LIST : [], null, function (k){ applyTemplate(k); }));\n      body.appendChild(mk('div', 'ed-hint', selText() ? 'Tap one to give the selected text that look.' : 'Tap one to add a text with that look at the playhead. Select a text first to change it instead.'));\n    } },\n    textanim: { title: 'Text animation', build: function (body){\n      var c = selText(); if (!c){ body.appendChild(mk('div', 'ed-hint', 'Tap a text on the timeline first.')); return; }\n      var an = Object.assign({ in: 'none', out: 'none', loop: 'none', inMs: 500, outMs: 500 }, c.anim || {});\n      var groups = [{ key: 'in', label: 'Comes in' }, { key: 'out', label: 'Goes out' }, { key: 'loop', label: 'While showing' }], g = chipKey('textanim', groups, 'in');\n      var OPTS = [{ key: 'none', label: 'None' }, { key: 'fade', label: 'Fade' }, { key: 'slideup', label: 'Slide up' }, { key: 'slidedown', label: 'Slide down' }, { key: 'pop', label: 'Pop' }];\n      var LOOPS = [{ key: 'none', label: 'None' }, { key: 'pulse', label: 'Pulse' }, { key: 'float', label: 'Float' }];\n      var set = function (o){ return P.setTextAnim(E.hist.cur, c.id, o); };\n      body.appendChild(chips(groups, g, pickChip('textanim')));\n      body.appendChild(chips(g === 'loop' ? LOOPS : OPTS, an[g], function (k){ var o = {}; o[g] = k; commit(set(o)); }));\n      if (g !== 'loop' && an[g] !== 'none'){ var lk = g + 'Ms'; body.appendChild(sliderRow('Length', 100, 2000, 100, an[lk], secs, null, function (v){ var o = {}; o[lk] = v; commit(set(o)); })); }\n      body.appendChild(mk('div', 'ed-hint', 'The slide and the pop move or grow the text as it comes or goes. Pulse breathes, Float drifts up and down.'));\n    } },\n    fxpick: { title: 'Effects', build: function (body){\n      var g = mk('div', 'ed-chips wrap');\n      (NL2 ? NL2.FX : []).forEach(function (x){ var b = btn(null, x.label, 'ed-chip'); b.onclick = function (){ addFxHere(x.key); }; g.appendChild(b); });\n      body.appendChild(g);\n      body.appendChild(mk('div', 'ed-hint', 'Tap one to put it on the picture at the playhead. Drag its ends on the timeline to change how long it lasts. Videos with effects export with the compatible engine, which takes longer.'));\n    } },\n    fxedit: { title: 'Effect', build: function (body){\n      var c = selFx(); if (!c){ body.appendChild(mk('div', 'ed-hint', 'Tap an effect on the timeline first.')); return; }\n      body.appendChild(chips(NL2.FX, c.fx, function (k){ commit(P.setFxProps(E.hist.cur, c.id, { fx: k })); }));\n      body.appendChild(sliderRow('Strength', 0, 100, 5, Math.round((c.strength == null ? 0.5 : c.strength) * 100), pct,\n        function (v){ live(P.setFxProps(E.hist.cur, c.id, { strength: v / 100 })); }, function (v){ commit(P.setFxProps(E.hist.cur, c.id, { strength: v / 100 })); }));\n      body.appendChild(mk('div', 'ed-hint', 'The preview is a close imitation. The exported video has the real effect.'));\n    } },\n","css":"\n/* extra Adjust layers and video effects in the preview */\n.ed-tint2{position:absolute;inset:0;pointer-events:none;mix-blend-mode:multiply;display:none}\n.ed-grain{position:absolute;inset:0;pointer-events:none;mix-blend-mode:overlay;display:none;opacity:0;\n  background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .5  0 0 0 0 .5  0 0 0 0 .5  0 0 0 1.6 -.3'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>\")}\n.ed-fxflash{position:absolute;inset:0;pointer-events:none;background:#fff;opacity:0}\n.ed-clip.k-fx{background:#8a2f6f;border-color:#d05db0}\n"};

function load(rel){ const f = path.join(root, rel); const raw = fs.readFileSync(f, 'utf8'); return { f, crlf: raw.includes('\r\n'), text: raw.replace(/\r\n/g, '\n') }; }
function save(o){ fs.writeFileSync(o.f, o.crlf ? o.text.replace(/\n/g, '\r\n') : o.text); }
const problems = [];
const nm = (o) => path.basename(o.f);
function rep(o, find, replace, label, times){
  const n = o.text.split(find).length - 1;
  if (n !== (times || 1)){ problems.push(label + ': found ' + n + ' times (need exactly ' + (times || 1) + ') in ' + nm(o)); return; }
  o.text = o.text.split(find).join(replace);
}
function repRe(o, re, replace, label){
  const m = o.text.match(new RegExp(re.source, 'g'));
  if (!m || m.length !== 1){ problems.push(label + ': found ' + (m ? m.length : 0) + ' times (need exactly 1) in ' + nm(o)); return; }
  o.text = o.text.replace(re, function (mm, g1){ return replace.replace('$1', g1 === undefined ? '' : g1); });
}
function seg(o, from, to, replace, label){
  const a = o.text.indexOf(from), b = a < 0 ? -1 : o.text.indexOf(to, a + 1);
  if (a < 0 || b < 0 || o.text.split(from).length !== 2){ problems.push(label + ': could not find the start/end markers in ' + nm(o)); return; }
  o.text = o.text.slice(0, a) + replace + o.text.slice(b);
}

